// Bundles the viewer (app.js + app.css + Cytoscape and its fcose layout) into one HTML
// template and writes it as an F# module, src/Haya.Core/ViewerAssets.fs. The generated file is committed so
// that `dotnet build` and Fable need no Node, and both stacks emit byte-identical html.
//
//   bun run gen-viewer.ts           write ViewerAssets.fs
//   bun run gen-viewer.ts --check   fail if the committed ViewerAssets.fs is out of date (CI)
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const here = import.meta.dir;
const target = join(here, "..", "Haya.Core", "ViewerAssets.fs");
const check = process.argv.includes("--check");

const read = (p: string) => readFileSync(join(here, p), "utf8");
const TOKENS = ["@@HAYA_TITLE@@", "@@HAYA_DATA@@", "@@HAYA_CSS@@", "@@HAYA_JS@@"];

// licence banner: MIT notices must survive minification
const packages = ["cytoscape", "cytoscape-fcose", "cose-base", "layout-base"];
const notice = packages.map((name) => {
  const dir = join(here, "node_modules", name);
  const pkg = JSON.parse(readFileSync(join(dir, "package.json"), "utf8"));
  const file = ["LICENSE", "LICENSE.md", "LICENSE.txt"].map((f) => join(dir, f)).find(existsSync);
  const text = file ? readFileSync(file, "utf8").trim() : `${pkg.license}`;
  return `${name}@${pkg.version} (${pkg.license})\n${text}`;
}).join("\n\n");
const banner = `/*! Third-party notices\n\n${notice.replaceAll("*/", "* /")}\n*/\n`;

const built = await Bun.build({ entrypoints: [join(here, "app.js")], minify: true, target: "browser", format: "iife" });
if (!built.success) { console.error(built.logs.join("\n")); process.exit(1); }
// `</script` inside inline JS would end the element early
const js = banner + (await built.outputs[0].text()).replaceAll("</script", "<\\/script");
const css = read("app.css").trim();
for (const [name, text] of [["app.js", js], ["app.css", css]] as const)
  for (const t of TOKENS) if (text.includes(t)) throw new Error(`${name} contains the reserved token ${t}`);

// the title and data are filled in at render time; css and js now
const template = read("index.html").replace("@@HAYA_CSS@@", () => css).replace("@@HAYA_JS@@", () => js);

// F# string literal: escape what would break it, plus the characters that differ between stacks
const esc = (s: string) => {
  let r = "";
  for (const ch of s) {
    const o = ch.codePointAt(0)!;
    if (ch === "\\") r += "\\\\";
    else if (ch === '"') r += '\\"';
    else if (ch === "\n") r += "\\n";
    else if (ch === "\r") r += "\\r";
    else if (ch === "\t") r += "\\t";
    else if (o < 32 || o === 0x2028 || o === 0x2029) r += "\\u" + o.toString(16).padStart(4, "0");
    else if (o > 0xffff) { const v = o - 0x10000; r += "\\u" + (0xd800 + (v >> 10)).toString(16) + "\\u" + (0xdc00 + (v & 0x3ff)).toString(16); }
    else r += ch;
  }
  return r;
};
const chunks: string[] = [];
for (let i = 0; i < template.length; i += 1500) {
  let end = Math.min(i + 1500, template.length);
  // do not split a surrogate pair
  if (end < template.length && /[\ud800-\udbff]/.test(template[end - 1]!)) end++;
  chunks.push(template.slice(i, end));
  i = end - 1500;
}
const fs = [
  "namespace Haya.Core",
  "",
  "/// GENERATED by src/Haya.Viewer/gen-viewer.ts. Do not edit. Regenerate with `bun run gen` in src/Haya.Viewer.",
  "module ViewerAssets =",
  "    /// The html page with the viewer's css and js inlined. `@@HAYA_TITLE@@` and `@@HAYA_DATA@@` are filled in at render time.",
  "    let template =",
  "        [",
  ...chunks.map((c) => `            \"${esc(c)}\"`),
  "        ]",
  "        |> String.concat \"\"",
  "",
].join("\n");

if (check) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current !== fs) { console.error("src/Haya.Core/ViewerAssets.fs is out of date. Run `bun run gen` in src/Haya.Viewer."); process.exit(1); }
  console.log("ViewerAssets.fs is up to date");
} else {
  writeFileSync(target, fs);
  console.log(`wrote ${target} (${template.length} chars, ${chunks.length} chunks)`);
}
